-- A person's flag: put on by a steward with a reason, in force while the sheet's today is on or before its
-- until-date (inclusive). While it is, the row shows the reason and only a steward may open a claim of theirs;
-- after it, it shows nothing and has no effect. A person has at most one: flagging them again replaces it.
CREATE TABLE person_flag (
    sheet_id   VARCHAR(255) NOT NULL,
    person_id  BIGINT       NOT NULL,
    reason     VARCHAR(1000) NOT NULL,
    until_date DATE         NOT NULL,
    PRIMARY KEY (sheet_id, person_id)
);
# POST /api/sheets/{sheetId}/people/{personId}/flag — flag a person (body: {reason, until, user}): a blank
# until-date takes the sheet's today. Flagging again replaces the flag. While the sheet's today is on or before
# the until-date the person's row shows the reason and only a steward may open a claim of theirs (alone, by
# bulk open or by a paste); after it the flag shows nothing and has no effect. Refused (400), storing nothing,
# when the user is not a steward, the reason is blank, the date is not valid or the person is not on the
# sheet. A stored flag is recorded in the audit file as PERSON_FLAGGED.
